{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Plecanatide, a large disulfide-rich peptide, showed negligible systemic availability after oral administration in humans, directly supporting low oral bioavailability for large peptide-based molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Aliskiren, a peptidomimetic renin inhibitor, has an absolute oral bioavailability of 2.6% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Hexarelin, a peptide GH secretagogue, had oral systemic availability of only 0.3% in humans, supporting low F for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "VX-985, a peptidic protease inhibitor, showed poor oral bioavailability from solid-form suspensions in rodents and humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "CGP 38 560, a peptide-like renin inhibitor, had oral bioavailability <1% in humans at 200 mg.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, a cyclic octapeptide, had absolute oral bioavailability of 0.6% in healthy volunteers, far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sampatrilat, a peptidomimetic ACE/NEP inhibitor, had systemic bioavailability of approximately 2% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "GHRP-6, a peptide GH secretagogue, had oral systemic availability of ~0.3% in humans, requiring extremely high oral doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Linaclotide, a large peptide, showed low systemic exposure and low oral bioavailability in humans, consistent with negligible absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, highly polar peptide-PEG-fatty acid conjugate. Nine high-transfer experimental analogues—ranging from large peptides to peptidomimetics—consistently show negligible to low oral bioavailability (0.3–3%) in humans. The physicochemical prior is also strongly unfavorable. The only high-F record (paliperidone ER, 28%) has negligible transferability and is structurally unrelated, so it does not outweigh the consistent low-F evidence. Therefore, absolute oral bioavailability is predicted to be below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Most supporting records report systemic availability or relative oral exposure rather than formal absolute F, though all are far below 20%.",
    "No data on formulation, prodrug, or active transport that could improve absorption of this large peptide conjugate.",
    "The single high-F record (paliperidone ER) has negligible transferability and is structurally unrelated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

